"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Sequencer } from "@/components/audio/elements/sequencer";
import { useStepClock } from "@/hooks/use-step-clock";

const initialPattern = [
  [true, false, false, false, true, false, false, false],
  [false, false, true, false, false, false, true, false],
];

export function SequencerPlayingDemo() {
  const [pattern, setPattern] = useState(initialPattern);
  const { isPlaying, start, step, stop } = useStepClock({
    bpm: 120,
    totalSteps: pattern[0]?.length ?? 0,
  });

  return (
    <div className="flex w-full max-w-lg flex-col gap-3">
      <Sequencer
        activeStep={isPlaying ? step : undefined}
        aria-label="Step pattern"
        onValueChange={setPattern}
        value={pattern}
      />
      <Button
        onClick={isPlaying ? stop : start}
        size="sm"
        type="button"
        variant="outline"
      >
        {isPlaying ? "Stop" : "Play"}
      </Button>
    </div>
  );
}
